    [pushToast],
  );

  const updateObservation = useCallback(
    async (observationId: string, payload: UpdateObservationPayload) => {
      try {
        const observation = await apiUpdateObservation(observationId, payload);
        setMemory((prev) =>
          observation.status === "dismissed"
            ? prev.filter((item) => item.id !== observationId)
            : prev.map((item) => (item.id === observationId ? observation : item)),
        );
        return observation;
      } catch {
        pushToast("error", "I couldn't update that context.");
        return null;
      }
    },
    [pushToast],
  );

  const deleteObservation = useCallback(
    async (observationId: string) => {
      try {
        await apiDeleteObservation(observationId);
        setMemory((prev) => prev.filter((item) => item.id !== observationId));
      } catch {
        pushToast("error", "I couldn't forget that.");
      }
    },
    [pushToast],
  );

  const clearMemory = useCallback(async () => {
    try {
      await apiClearMemory();
      setMemory([]);
      setConversationId(null);
      setMessages([]);
      setToolActivity([]);
    } catch {
      pushToast("error", "I couldn't clear what I've learned.");
    }
  }, [pushToast]);

  const clearChat = useCallback(() => {
    abortRef.current?.abort();
    abortRef.current = null;
    setMessages([]);
    setToolActivity([]);
    setStreaming(false);
    setThinkingPhase(null);
    setOfflineReply(false);
    setConversationId(null);
    void apiCreateConversation()
      .then((conversation) =>
        setConversationId((current) => current ?? conversation.id),
      )
      .catch(() => undefined);
  }, []);

  // Initial hydration: env defaults, canvas, health probes.
  useEffect(() => {
    let cancelled = false;

    async function boot() {
      try {
        const defaults = await fetchConfig();
        if (!cancelled) {
          setSidecarReachable(true);
          if (localStorage.getItem(SETTINGS_KEY) === null) {
            saveSettings(defaults);
          }
        }
      } catch {
        if (!cancelled) {
          setSidecarReachable(false);
        }
      }
      if (cancelled) {
        return;
      }
      void refreshCanvas();
      void refreshConnectors();
      void refreshPresets();
      void refreshMemory();
      void fetchLatestConversation()
        .then(async ({ conversation }) => {
          if (cancelled || !conversation) {
            return;
          }
          setConversationId(conversation.id);
          // The tree, not the flat turn list: a conversation with branches
          // must open on the branch that was visible when it was left.
          const tree = await fetchConversationTree(conversation.id);
          if (cancelled) {
            return;
          }
          setMessages(turnsToMessages(tree.messages, tree.head_id));
        })
        .catch(() => undefined);
      void healthMcp(settings.mcp_url)
        .then((result) => {
          if (!cancelled) {
            setMcpReachable(result.reachable);
          }
        })
        .catch(() => undefined);
      void healthLlm({
        base_url: settings.base_url,
        api_key: settings.api_key,
        model: settings.model_name,
      })
        .then((result) => {
          if (!cancelled) {
            setLlmHealth(result);
          }
        })
        .catch(() => undefined);
    }

    void boot();
    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Health polling: the studio must notice that the model or the MCP server
  // came back without a reload, so the bar leaves "Local mode" on its own.
  useEffect(() => {
    const poll = () => {
      if (document.visibilityState === "visible") {
        void checkConnections();
      }
    };

    const timer = window.setInterval(poll, HEALTH_POLL_INTERVAL_MS);
    document.addEventListener("visibilitychange", poll);

    return () => {
      window.clearInterval(timer);
      document.removeEventListener("visibilitychange", poll);
    };
  }, [checkConnections]);

  // The canvas is one state, not four booleans: an empty board and a failed
  // board must never look the same.
  const canvas = canvasState.data;
  const canvasLoading = canvasState.kind === "loading";
  const canvasError = canvasState.kind === "error" ? canvasState.error : null;

  const value = useMemo<StudioContextValue>(
    () => ({
      settings,
      saveSettings,
      displayName,
      setDisplayName,
      brief,
      saveBrief,
      setupOpen,
      openSetup,
      closeSetup,
      canvas,
      canvasLoading,
      canvasCached,
      canvasState,
      canvasError,
      refreshCanvas,
      llmHealth,
      mcpReachable,
      sidecarReachable,
      checkConnections,
      messages,
      streaming,
      thinkingPhase,
      toolActivity,
      sendMessage,
      regenerateFrom,
      editFrom,
      switchBranch,
      respondToApproval,
      stopStreaming,
      clearChat,
      conversationId,
      memory,
      memoryLoading,
      refreshMemory,
      addObservation,
      updateObservation,
      deleteObservation,
      clearMemory,
      pushNotice,
      offlineReply,
      addStep,
      addOutcome,
      createJob,
      updateJob,
      deleteJob,
      updateStep,
      deleteStep,
      updateOutcome,
      deleteOutcome,
      activePanel,
      openPanel,
      closePanel,
      ask,
      toasts,
      pushToast,
      dismissToast,
      connectors,
      connectorsError,
      presets,
      presetError,
      refreshConnectors,
      refreshPresets,
      addConnector,
      deleteConnector,
      connectorSuggestions,
      dismissConnectorSuggestion,
      notifications,
      unreadNotificationCount,
      markNotificationAsRead,
      markAllNotificationsAsRead,
      dismissNotification,
      addNotification,
      simulateBackgroundEvent,
    }),
    [
      settings,
      saveSettings,
      displayName,
      setDisplayName,
      brief,
      saveBrief,
      setupOpen,
      openSetup,
      closeSetup,
      canvas,
      canvasLoading,
      canvasCached,
      canvasState,
      canvasError,
      refreshCanvas,
      llmHealth,
      mcpReachable,
      sidecarReachable,
      checkConnections,
      messages,
      streaming,
      thinkingPhase,
      toolActivity,
      sendMessage,
      regenerateFrom,
      editFrom,
      switchBranch,
      respondToApproval,
      stopStreaming,
      clearChat,
      conversationId,
      memory,
      memoryLoading,
      refreshMemory,
      addObservation,
      updateObservation,
      deleteObservation,
      clearMemory,
      pushNotice,
      offlineReply,
      addStep,
      addOutcome,
      createJob,
      updateJob,
      deleteJob,
      updateStep,
      deleteStep,
      updateOutcome,
      deleteOutcome,
      activePanel,
      openPanel,
      closePanel,
      ask,
      toasts,
      pushToast,
      dismissToast,
      connectors,
      connectorsError,
      presets,
      presetError,
      refreshConnectors,
      refreshPresets,
      addConnector,
      deleteConnector,
      connectorSuggestions,
      dismissConnectorSuggestion,
      notifications,
      unreadNotificationCount,
      markNotificationAsRead,
      markAllNotificationsAsRead,
      dismissNotification,
      addNotification,
      simulateBackgroundEvent,
    ],
  );

  return <StudioContext.Provider value={value}>{children}</StudioContext.Provider>;
}

export function useStudio(): StudioContextValue {
  const context = useContext(StudioContext);
  if (!context) {
    throw new Error("useStudio must be used within a StudioProvider");
  }
  return context;
}

